CREATE TABLE IF NOT EXISTS organizationSubscriptions (id INT PRIMARY KEY AUTO_INCREMENT, organizationId INT NOT NULL, planId INT NOT NULL, status ENUM('active', 'cancelled', 'expired', 'pending') DEFAULT 'active', startDate DATETIME NOT NULL, endDate DATETIME, autoRenew BOOLEAN DEFAULT true, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS featureAccess (id INT PRIMARY KEY AUTO_INCREMENT, organizationId INT NOT NULL, feature VARCHAR(255) NOT NULL, isEnabled BOOLEAN DEFAULT true, customConfig JSON, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS invoices (id INT PRIMARY KEY AUTO_INCREMENT, organizationId INT NOT NULL, subscriptionId INT, invoiceNumber VARCHAR(100) NOT NULL UNIQUE, amount DECIMAL(10, 2) NOT NULL, currency VARCHAR(3) DEFAULT 'USD', status ENUM('draft', 'sent', 'paid', 'overdue', 'cancelled') DEFAULT 'draft', dueDate DATETIME, paidDate DATETIME, pdfUrl VARCHAR(500), createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);

